public class Power {
    public double myPow(double x, int n) {
        if (n < 0) { x = 1 / x; n = -n; }
        double result = 1;
        while (n > 0) {
            if (n % 2 == 1) result *= x;
            x *= x;
            n /= 2;
        }
        return result;
    }
    public static void main(String[] args) {
        System.out.println(new Power().myPow(2, 10)); // 1024.0
        System.out.println(new Power().myPow(3, 5));  // 243.0
    }
}

